def state(phase="fight", battle=1, finished=False):
    def robot(rid, x):
        return {"id": rid, "present": True, "center": [x, 350.0], "vel": [0.0, 0.0], "radius": 40.0,
                "contour": [[x - 40, 310], [x + 40, 310], [x + 40, 390], [x - 40, 390]], "hp": 80.0,
                "max_hp": 100.0, "outside": False, "ulti": {"charge": 0.5, "ready": False, "used": False}}

    return {"phase": phase, "battle": battle, "finished": finished, "elapsed": 12.3,
            "arena": {"size": [1000.0, 700.0]}, "robots": [robot(1, 300.0), robot(2, 600.0)],
            "zone": [[50, 40], [950, 40], [950, 660], [50, 660]],
            "items": [{"kind": "heal", "center": [500.0, 100.0],
                       "poly": [[530, 100], [500, 130], [470, 100], [500, 70]]}],
            "frame": {"w": 1000.0, "h": 700.0, "kind": "arena", "pad": 80}}


def jpeg(w=1160, h=860):
    ok, out = cv2.imencode(".jpg", np.full((h, w, 3), 90, np.uint8))
    return out.tobytes()


# ---------- Lagebild ----------

def test_snapshot_reads_server_state():
    snap = snapshot_from(state(), 2, fresh=True)
    assert snap.fighting and snap.battle == 1 and snap.elapsed == 12.3
    assert snap.me.pos.tolist() == [600.0, 350.0] and snap.foe.pos.tolist() == [300.0, 350.0]
    assert snap.me.hp == 80.0 and snap.me.outline.shape == (4, 2)
    assert snap.bounds == (50.0, 40.0, 950.0, 660.0)
    assert snap.ulti == "lädt 50 %"
    kind, center, radius = snap.items[0]
    assert kind == "heal" and center.tolist() == [500.0, 100.0] and radius == pytest.approx(30.0)
    # Alter Zustand oder Ende: nicht mehr kämpfen, sonst fährt der Roboter blind weiter.
    assert not snapshot_from(state(), 2, fresh=False).fighting
    assert not snapshot_from(state(finished=True), 2, fresh=True).fighting
    assert not snapshot_from(None, 2, fresh=True).fighting


def test_picture_is_scaled_to_image_px():
    snap = snapshot_from(state(), 1, fresh=True)
    out = picture(snap, jpeg(), state()["frame"], 0.0, 512)
    img = cv2.imdecode(np.frombuffer(base64.b64decode(out), np.uint8), cv2.IMREAD_COLOR)
    assert img.shape[1] == 512 and img.shape[0] == round(860 * 512 / 1160)
    assert picture(snap, jpeg(), {"kind": "camera", "w": 640, "h": 480}, None, 512) is None


# ---------- Regler ----------

def snap(me_pos, foe_pos, bounds=(0.0, 0.0, 1000.0, 700.0)):
    me = Body(True, np.array(me_pos, np.float32), np.zeros(2, np.float32), 40.0)
    foe = Body(True, np.array(foe_pos, np.float32), np.zeros(2, np.float32), 40.0)
    return Snapshot("fight", 1, True, 1.0, (1000.0, 700.0), bounds, me, foe, "lädt 0 %", [])


def heading(angle):
    h = Heading()
    h.angle, h.key, h.since = angle, "w", 0.0
    return h


def test_heading_comes_from_motion():
    h = Heading()
    me = Body(True, np.zeros(2, np.float32), np.array([0.0, 200.0], np.float32), 40.0)
    h.update("w", me, 0.0)
    h.update("w", me, 0.1)
    assert h.angle is None
    h.update("w", me, 0.3)
    assert h.angle == pytest.approx(math.pi / 2)
    h.update("s", me, 0.4)
    h.update("s", me, 0.7)
    assert h.angle == pytest.approx(-math.pi / 2)
    h.update("d", me, 0.8)
    assert h.angle is None


def test_driver_rams_and_turns_towards_foe():
    d = Driver()
    d.set("ram", 1)
    assert d.key(snap((300, 350), (600, 350)), heading(0.0), 0.0) == "w"
    # Gegner unten (positiver Winkel im Bild) heißt rechts herum drehen, danach ein Stück vor.
    d2 = Driver()
    d2.set("ram", 1)
    assert d2.key(snap((300, 350), (300, 600)), heading(0.0), 0.0) == "d"
    assert d2.key(snap((300, 350), (300, 600)), heading(0.0), 0.5) == "w"
    d3 = Driver()
    d3.set("ram", 1)
    assert d3.key(snap((300, 350), (300, 100)), heading(0.0), 0.0) == "a"


def test_driver_backs_off_from_edge_and_holds():
    d = Driver()
    d.set("ram", 1)
    assert d.key(snap((960, 350), (600, 350)), heading(0.0), 0.0) == "s"
    d.set("hold", 1)
    assert d.key(snap((500, 350), (600, 350)), heading(0.0), 5.0) == STOP


# ---------- Ganze Runde ----------

class FakeSession:
    def __init__(self, owner, tools):
        self.owner = owner
        self.tools = {t.name: t for t in tools}

    async def send_and_wait(self, prompt, attachments=None, timeout=None):
        self.owner.turns.append((prompt, attachments))
        for name, args in self.owner.script:
            await self.tools[name].handler(ToolInvocation(tool_name=name, arguments=args))
        return SimpleNamespace(data=SimpleNamespace(content="Ich ramme ihn."))

    async def disconnect(self):
        pass

    async def abort(self):
        pass


class FakeClient:
    """Statt Copilot: jede Runde ruft dieselben Werkzeuge auf."""

    def __init__(self, script=()):
        self.script = list(script)
        self.turns = []
        self.sessions = []

    def __call__(self, token):
        self.token = token
        return self

    async def start(self):
        pass

    async def stop(self):
        pass

    async def create_session(self, **kw):
        self.sessions.append(kw)
        return FakeSession(self, kw["tools"])


def make_pilot(fake, monkeypatch, refuse_status=False):
    monkeypatch.setattr(pilot, "STATUS_S", 0.05)
    p = Pilot("server:8765", "tok", 2, Setup("sonnet", "Sonnet", None, "taktik", "", "", turn_s=0.05), fake)
    posts = []

    def post(path, data):
        posts.append((path, data))
        if refuse_status and path == "/api/ai_status":
            return 403, {"ok": False, "message": "Du hast gerade keinen Spielerplatz."}
        return 200, {"ok": True}

    async def read():
        # Statt WebSocket: der Server schickt laufend Zustand und Bild.
        while True:
            p.state, p.received = state(), time.monotonic()
            p.jpeg, p.frame = jpeg(), p.state["frame"]
            await asyncio.sleep(0.02)

    p.post = post
    p._read = read
    return p, posts


async def until(cond, timeout=10.0):
    deadline = time.monotonic() + timeout
    while not cond():
        assert time.monotonic() < deadline, "Bedingung nicht rechtzeitig erfüllt"
        await asyncio.sleep(0.02)


def test_pilot_fights_with_image_and_tools(monkeypatch):
    fake = FakeClient(script=[("set_tactic", {"tactic": "push_out", "side": "left"}),
                              ("say", {"text": "Tschüss!"}), ("ulti", {})])
    p, posts = make_pilot(fake, monkeypatch)

    async def scenario():
        task = asyncio.create_task(p.main())
        await until(lambda: len(fake.turns) >= 2 and any(x[0] == "/api/ai_status" for x in posts))
        task.cancel()
        with contextlib.suppress(asyncio.CancelledError):
            await task

    asyncio.run(scenario())
    prompt, attachments = fake.turns[0]
    assert "HP" in prompt and "Ulti: lädt 50 %" in prompt
    assert attachments[0]["mimeType"] == "image/jpeg" and len(attachments[0]["data"]) > 1000
    session = fake.sessions[0]
    assert {t.name for t in session["tools"]} == {"set_tactic", "ulti", "say"}
    assert session["skip_custom_instructions"] is True
    assert p.driver.tactic == "push_out" and p.driver.side == -1
    assert ("/api/say", {"text": "Tschüss!"}) in posts and ("/api/ulti", {}) in posts
    status = next(d["status"] for path, d in posts if path == "/api/ai_status")
    assert status["model"] == "Sonnet" and status["robot"] == "Probelauf"
    assert status["bluetooth"] == "Probelauf"
    assert p.comment == "Ich ramme ihn." and p.bt.key == STOP


def test_kick_ends_the_pilot(monkeypatch):
    p, _ = make_pilot(FakeClient(), monkeypatch, refuse_status=True)
    with pytest.raises(PilotError, match="Moderation"):
        asyncio.run(asyncio.wait_for(p.main(), 10))
    assert p.bt.key == STOP

def test_runtime_install_retries_then_gives_up(monkeypatch):
    monkeypatch.delenv("COPILOT_CLI_PATH", raising=False)
    monkeypatch.setattr(pilot.time, "sleep", lambda _s: None)
    calls = []

    def flaky():
        calls.append(1)
        if len(calls) < 2:
            raise PermissionError("gesperrt")

    pilot._ensure_runtime(flaky)
    assert len(calls) == 2

    def locked():
        raise PermissionError("gesperrt")

    with pytest.raises(PilotError, match="Virenscanner"):
        pilot._ensure_runtime(locked)


def test_openai_models_filter_and_effort(monkeypatch):
    ids = ["gpt-4.1-mini", "gpt-4o-2024-08-06", "gpt-5", "gpt-4o-realtime-preview", "o4-mini", "o3-mini",
           "text-embedding-3-small", "dall-e-3", "gpt-5-chat-latest"]

    def urlopen(req, timeout):
        assert req.full_url.endswith("/models")
        assert req.get_header("Authorization") == "Bearer sk-test"
        return io.BytesIO(json.dumps({"data": [{"id": i} for i in ids]}).encode())

    monkeypatch.setattr(pilot.urllib.request, "urlopen", urlopen)
    models = pilot._openai_models("sk-test")
    assert [(m["id"], m["effort"]) for m in models] == [("gpt-4.1-mini", None), ("gpt-5", "low"),
                                                         ("o4-mini", "low")]


def test_openai_rejects_bad_key(monkeypatch):
    def urlopen(req, timeout):
        raise urllib.error.HTTPError(req.full_url, 401, "Unauthorized", None, None)

    monkeypatch.setattr(pilot.urllib.request, "urlopen", urlopen)
    with pytest.raises(PilotError, match="lehnt den Schlüssel ab"):
        pilot._openai_models("sk-falsch")


@pytest.mark.parametrize(("model", "effort", "wire"), [("gpt-4.1-mini", None, None),
                                                      ("gpt-5.6-sol", "low", "responses")])
def test_openai_key_reaches_session_without_github(monkeypatch, model, effort, wire):
    fake = FakeClient(script=[("set_tactic", {"tactic": "push_out", "side": "left"})])
    p, _posts = make_pilot(fake, monkeypatch)
    p.cfg = Setup(model, model, effort, "taktik", "", "", turn_s=0.05, api_key="sk-test")

    async def scenario():
        task = asyncio.create_task(p.main())
        await until(lambda: fake.turns)
        task.cancel()
        with contextlib.suppress(asyncio.CancelledError):
            await task

    asyncio.run(scenario())
    assert fake.token is None
    provider = fake.sessions[0]["provider"]
    assert provider["type"] == "openai" and provider["api_key"] == "sk-test"
    assert provider.get("wire_api") == wire
    assert fake.sessions[0].get("reasoning_effort") == effort
